\section{Search space}
\label{appsearchspace}
The operands and operations to populate our search space are the following ($i$ indexes the current layer):

\begin{itemize}
    \item \textbf{Operands:}
    \begin{itemize}
        \item $W_i$, $\sgn(W_i)$ (weight matrix of the current layer and sign of it),
        \item $R_i$ , $S_i$ (Gaussian and Bernoulli random matrices, same shape as $W_i$),
        \item $R_{L i}$ (Gaussian random matrix mapping from $b^p_L$ to $b^p_i$),
        \item $h^p_i$, $h_i$, $h^p_{i+1}$ (hidden activations of the forward propagation),
        \item $b^p_L$, $b^p_{i+1}$ (backward propagated values),
        \item $b^p_{i+1} \frac{\partial h^p_{i+1}}{\partial  h_{i}}$, $b^p_{i+1} \frac{\partial h^p_{i+1}}{\partial  h^p_{i}}$ (backward propagated values according to gradient backward propagation),
        \item $b^p_{i+1} \cdot R_i$, $(b^p_{i+1} \cdot R_i) \odot \frac{\partial h_{i}}{\partial  h^p_{i}}$ (backward propagated values according to feedback alignment),

\item $b^p_{L} \cdot R_{L i}$, $(b^p_{L} \cdot R_{L i}) \odot \frac{\partial h_{i}}{\partial  h^p_{i}}$ (backward propagated values according to direct feedback alignment).
    \end{itemize}
    \item \textbf{Unary functions $u(x)$:}
    \begin{itemize}
        \item $x$ (identity), $x^t$ (transpose), $1/x$, $\lvert x \rvert$, $-x$ (negation), $\mathds{1}_{x > 0}$ ($1$ if $x$ greater than $0$), $x^+$ (ReLU), $\sgn(x)$ (sign),
    $\sqrt{\lvert x \rvert}$, $\sgn(x) \sqrt{\lvert x \rvert}$, $x^2$, $\sgn(x) x^2$, $x^3$, $a x$, $x + b$,
        \item $x + \gnoise(g)$, $x \odot (1+\gnoise(g))$ (add or multiply with Gaussian noise of scale $g \in (0.01, 0.1, 0.5, 1.0)$),

\item $\drop_d(x)$ (dropout with drop probability $d \in (0.01, 0.1, 0.3)$), $\clip_c(x)$ (clip values in range $[-c, c]$ and $c \in (0.01, 0.1, 0.5, 1.0$), 
        \item $\enorm{x}_0$, $\enorm{x}_1$, $\enorm{x}_2$, $\enorm{x}_{-inf}$, $\enorm{x}_{inf}$ (normalizing term by vector norm on flattened matrix),
        \item $\colnorm{x}_0$, $\colnorm{x}_1$, $\colnorm{x}_2$, $\colnorm{x}_{-inf}$, $\colnorm{x}_{inf}$,
    $\rownorm{x}_0$, $\rownorm{x}_1$, $\rownorm{x}_2$, $\rownorm{x}_{-inf}$, $\rownorm{x}_{inf}$,(normalizing term by vector norm along columns or rows of matrix),
        \item $\norm{x}_{fro}$, $\norm{x}_1$, $\norm{x}_{-inf}$, $\norm{x}_{inf}$ (normalizing term by matrix norm),
        \item $(x-\hat{m}(x)) / \sqrt{\hat{s}(x^2)}$ (normalizing with running averages with factor $r = 0.9$).
    \end{itemize}
    \item \textbf{Binary functions $f(x, y)$:}
    \begin{itemize}

\end{itemize}
    \item \textbf{Binary functions $f(x, y)$:}
    \begin{itemize}
        \item $x + y$, $x - y$, $x \odot y$, $x / y$ (element-wise addition, subtraction, multiplication, division),
        \item $x \cdot y$ (matrix multiplication),
        \item $x$ (keep left),
        \item $\min(x, y)$, $\max(x, y)$ (minimum and maximum of $x$ and $y$).
    \end{itemize}
\end{itemize}
